import java.util.*;

class Example {
    static class Range implements Iterable<Integer> {
        private final int end;

        Range(int end) {
            this.end = end;
        }

        @Override
        public Iterator<Integer> iterator() {
            return new Iterator<>() {
                int i = 0;

                public boolean hasNext() {
                    return i < end;
                }

                public Integer next() {
                    return i++;
                }
            };
        }
    }

    public static void main(String[] args) {
        for (int n : new Range(3)) {
            System.out.print(n);
        }
    }
}

